const rows = $input.all();

if (!rows.length) return [{ json: { sql: null } }];

const valueSets = rows.map(r => {
  const d = r.json;
  return `('${d.company_id}', '${d.month}', ${d.revenue}, ${d.expenses}, ${d.profit})`;
}).join(', ');

const sql = `INSERT INTO finance_monthly_pl (company_id, month, revenue, expenses, profit)
  VALUES ${valueSets}
  ON CONFLICT (company_id, month) DO UPDATE SET
    revenue = EXCLUDED.revenue,
    expenses = EXCLUDED.expenses,
    profit = EXCLUDED.profit,
    updated_at = NOW()`;

return [{ json: { sql } }];
